        ('c0000018-0000-0000-0000-000000000132'::uuid, 'b0000018-0000-0000-0000-000000000008'::uuid, 'GP-JA-N5-011', 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Bagaimana cuaca hari ini?', '{"audio_text":"きょうは はれですが、かぜが つよいです。","options":[{"id":"opt_1","text":"Cerah tapi anginnya kencang"},{"id":"opt_2","text":"Hujan lebat sepanjang hari"},{"id":"opt_3","text":"Berawan dan dingin"},{"id":"opt_4","text":"Turun salju di sore hari"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'はれ (cerah) + かぜが つよい (anginnya kencang).', 4),
