        ('c0000018-0000-0000-0000-000000000134'::uuid, 'b0000018-0000-0000-0000-000000000008'::uuid, 'GP-JA-N5-012', 'writing', 'sentence_builder', 'Susun kalimat kekaguman tempat: "Gunung Fuji adalah gunung terkenal di Jepang."', '{"tokens":["ふじさん","は","ゆうめいな","やま","です"],"target_translation":"Gunung Fuji adalah gunung terkenal.","romaji":"Fujisan wa yuumeina yama desu."}'::jsonb, '["ふじさん","は","ゆうめいな","やま","です"]'::jsonb, NULL::jsonb, NULL::jsonb, 'ゆうめい adalah kata sifat-na sehingga wajib memakai な sebelum やま (gunung).', 6),
        ('c0000018-0000-0000-0000-000000000135'::uuid, 'b0000018-0000-0000-0000-000000000008'::uuid, 'GP-JA-N5-011', 'listening', 'listening_choice', 'Dengarkan percakapan musim berikut. Musim apakah yang paling tidak disukai pembicara?', '{"audio_text":"ふゆは さむいから きらいです。","options":[{"id":"opt_1","text":"Musim dingin karena dingin"},{"id":"opt_2","text":"Musim panas karena lembap"},{"id":"opt_3","text":"Musim hujan karena becek"},{"id":"opt_4","text":"Musim gugur karena sepi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'ふゆ (musim dingin) + さむいから (karena dingin) + きらい (tidak suka).', 7),
