        ('c0000018-0000-0000-0000-000000000140'::uuid, 'b0000001-0000-0000-0000-000000000024'::uuid, 'GP-JA-N5-014', 'listening', 'listening_choice', 'Dengarkan permintaan atasan ini. Apa yang diminta untuk dilakukan?', '{"audio_text":"ドアを しめて ください。","options":[{"id":"opt_1","text":"Menutup pintu"},{"id":"opt_2","text":"Membuka jendela"},{"id":"opt_3","text":"Mematikan AC"},{"id":"opt_4","text":"Mencetak dokumen"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'ドアを しめて ください berarti tolong tutup pintunya.', 7),
