        ('c0000018-0000-0000-0000-000000000168'::uuid, 'b0000018-0000-0000-0000-000000000010'::uuid, 'GP-JA-N5-014', 'listening', 'listening_choice', 'Dengarkan rencana libur berikut. Apa saja kegiatannya?', '{"audio_text":"やすみは せんたくしたり、料理（りょうり）したり します。","options":[{"id":"opt_1","text":"Mencuci baju dan memasak"},{"id":"opt_2","text":"Tidur dan mendaki gunung"},{"id":"opt_3","text":"Belanja dan berenang"},{"id":"opt_4","text":"Belajar dan bekerja lembur"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'せんたく (mencuci pakaian) + りょうり (memasak).', 3),
