        ('c0000018-0000-0000-0000-000000000212'::uuid, 'b0000018-0000-0000-0000-000000000012'::uuid, 'GP-JA-N5-016', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Barang apa yang dipinjam oleh pembicara?', '{"audio_text":"ともだちに かさを かりました。","options":[{"id":"opt_1","text":"Payung"},{"id":"opt_2","text":"Kamus kanji"},{"id":"opt_3","text":"Sepeda lipat"},{"id":"opt_4","text":"Kamera digital"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'かさを かりました berarti meminjam payung.', 7),
