        ('c0000018-0000-0000-0000-000000000219'::uuid, 'b0000018-0000-0000-0000-000000000013'::uuid, 'GP-JA-N5-016', 'listening', 'listening_choice', 'Dengarkan hobi berikut. Apa kemahiran pembicara?', '{"audio_text":"ピアノを ひくことが できます。","options":[{"id":"opt_1","text":"Bisa bermain piano"},{"id":"opt_2","text":"Bisa bernyanyi opera"},{"id":"opt_3","text":"Bisa melukis cat air"},{"id":"opt_4","text":"Bisa memasak sushi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'ピアノを ひく (bermain piano) + ことができます (bisa).', 5),
