        ('c0000018-0000-0000-0000-000000000223'::uuid, 'b0000018-0000-0000-0000-000000000013'::uuid, 'GP-JA-N5-016', 'reading', 'fill_blank', 'Untuk menyatakan perubahan bertahap ("menjadi lebih mahir") dipakai:', '{"sentence_template":"毎日 練習して、日本語 が じょうず に [blank]。","translation":"Karena berlatih tiap hari, bahasa Jepangku jadi mahir.","options":["なりました","しました","できました","いきました"]}'::jsonb, '{"selected":"なりました"}'::jsonb, NULL::jsonb, NULL::jsonb, '[Kata Sifat-Na] + に なります menyatakan perubahan menjadi sesuatu.', 9),
