        ('c0000018-0000-0000-0000-000000000227'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-009', 'listening', 'listening_choice', 'Dengarkan dialog konfirmasi ruang rapat. Di mana letak ruang Sakura?', '{"audio_text":"さくらのかいぎしつは ３がいの みぎがわに あります。","options":[{"id":"opt_1","text":"Di lantai 3 sebelah kanan"},{"id":"opt_2","text":"Di lantai 2 sebelah kiri"},{"id":"opt_3","text":"Di lantai 1 dekat lobi"},{"id":"opt_4","text":"Di lantai 4 paling ujung"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, '３がい (lantai 3) + みぎがわ (sebelah kanan).', 3),
        ('c0000018-0000-0000-0000-000000000228'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-004', 'reading', 'fill_blank', 'Partikel yang menunjukkan alat/bahasa yang digunakan saat menulis adalah:', '{"sentence_template":"にほんご [blank] レポート を かきます。","translation":"Menulis laporan dengan bahasa Jepang.","options":["で","を","に","と"]}'::jsonb, '{"selected":"で"}'::jsonb, NULL::jsonb, NULL::jsonb, 'Bahasa dan alat tulis memakai partikel で.', 4),
        ('c0000018-0000-0000-0000-000000000229'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-016', 'writing', 'sentence_builder', 'Susun kalimat gabungan sebab-akibat: "Karena macet, saya naik kereta bawah tanah."', '{"tokens":["みち","が","こんでいますから","ちかてつ","で","いきます"],"target_translation":"Karena macet, naik kereta bawah tanah.","romaji":"Michi ga konde imasu kara chikatetsu de ikimasu."}'::jsonb, '["みち","が","こんでいますから","ちかてつ","で","いきます"]'::jsonb, NULL::jsonb, NULL::jsonb, 'こんでいます (sedang macet) + から menjelaskan alasan.', 5),
        ('c0000018-0000-0000-0000-000000000230'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-015', 'listening', 'listening_choice', 'Dengarkan kabar berikut. Apa yang sedang dipelajari oleh pembicara?', '{"audio_text":"いま 日本語の 文法（ぶんぽう）を ならっています。","options":[{"id":"opt_1","text":"Tata bahasa Jepang"},{"id":"opt_2","text":"Masakan tradisional"},{"id":"opt_3","text":"Kaligrafi kuas"},{"id":"opt_4","text":"Ekonomi internasional"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'ぶんぽう (bunpou) berarti tata bahasa / grammar.', 6),
        ('c0000018-0000-0000-0000-000000000231'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-012', 'reading', 'fill_blank', 'Kata sifat-i "せまい" (sempit) jika diubah menjadi "menjadi tidak sempit" / negatif:', '{"sentence_template":"新しい オフィス は まったく [blank] です。","translation":"Kantor baru sama sekali tidak sempit.","options":["せまくない","せまいじゃない","せまな","せまかった"]}'::jsonb, '{"selected":"せまくない"}'::jsonb, NULL::jsonb, NULL::jsonb, 'せまい → hapus い + くない = せまくない.', 7),
        ('c0000018-0000-0000-0000-000000000232'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-014', 'writing', 'sentence_builder', 'Susun kalimat pengingat akhir sesi: "Jangan lupa periksa kartu flashcard setiap hari."', '{"tokens":["まいにち","フラッシュカード","を","みてください"],"target_translation":"Lihat flashcard setiap hari.","romaji":"Mainichi furasshukaado o mite kudasai."}'::jsonb, '["まいにち","フラッシュカード","を","みてください"]'::jsonb, NULL::jsonb, NULL::jsonb, 'Verba みます + てください = tolong lihat / pelajari.', 8),
        ('c0000018-0000-0000-0000-000000000233'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-016', 'listening', 'listening_choice', 'Dengarkan kalimat penutup N5 ini. Apa kesiapan pembicara?', '{"audio_text":"N5の しけんを がんばる つもりです！","options":[{"id":"opt_1","text":"Bertekad berjuang di ujian N5"},{"id":"opt_2","text":"Sudah menyerah ikut ujian"},{"id":"opt_3","text":"Baru mendaftar minggu depan"},{"id":"opt_4","text":"Sedang menunggu pengumuman lulus"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL::jsonb, NULL::jsonb, 'がんばる つもりです berarti bertekad berusaha keras.', 9),
        ('c0000018-0000-0000-0000-000000000234'::uuid, 'b0000018-0000-0000-0000-000000000014'::uuid, 'GP-JA-N5-013', 'reading', 'fill_blank', 'Menutup sesi belajar dengan mengajak beristirahat bersama:', '{"sentence_template":"ちょっと [blank] ましょうか。","translation":"Mari kita beristirahat sebentar.","options":["やすみ","やすむ","やすんで","やすめ"]}'::jsonb, '{"selected":"やすみ"}'::jsonb, NULL::jsonb, NULL::jsonb, '～ましょう menempel pada bentuk stem ます (やすみます → やすみ).', 10)
)
INSERT INTO exercises (
    id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt,
    content, correct_answer, acceptable_answers, diagnostic_rubric, explanation, order_index
)
SELECT
    es.ex_id,
    es.lesson_id,
    gp.id,
    es.skill_pillar,
    es.exercise_type,
    es.prompt,
    es.content,
    es.correct_answer,
    es.acceptable_answers,
    es.diagnostic_rubric,
    es.explanation,
    es.order_index
FROM exercise_seed es
LEFT JOIN grammar_points gp ON gp.code = es.gp_code
ON CONFLICT (id) DO NOTHING;
